/* 好感度圆点渲染（含色彩渐变）
   颜色规则：低→青碧(jade)，中→金黄(ochre)，高→朱红(cinnabar) */
function dots(containerId, numId, val){
  var n = Math.max(0, Math.min(100, parseInt(val) || 0));
  var f = Math.floor(n / 10);
  var h = (n % 10) >= 5;
  var s = '';

  for (var i = 0; i < 10; i++) {
    var level;
    if (i < 3)       level = 'level-low';   // 0-29  青碧
    else if (i < 7)  level = 'level-mid';   // 30-69 金黄
    else             level = 'level-high';  // 70-100 朱红

    var cls = 'gf-dot ' + level;
    if (i < f)            cls += ' filled';
    else if (i === f && h) cls += ' half';

    s += '<span class="' + cls + '"></span>';
  }

  var el = document.getElementById(containerId);
  var numEl = document.getElementById(numId);
  if (el) el.innerHTML = s;
  if (numEl) numEl.textContent = n + ' / 100';
}

/* 渲染服饰分行：从 stat_data 读取 7 个子键，生成分行 HTML */
function renderClothes(d, prefix, containerId){
  var keys = ['外衣','内搭','贴身层','下装','鞋袜','发饰','配饰'];
  var html = '';
  keys.forEach(function(k){
    var val = _.get(d, prefix + '.' + k, '');
    if (val) {
      html += '<span class="gf-clo-item"><span class="gf-clo-label">' + k + '</span><span class="gf-clo-desc">' + val + '</span></span>';
    }
  });
  $('#' + containerId).html(html);
}

/* 主渲染：从 stat_data 实时读取并填充
   任何一步失败都保持 HTML 兜底默认值，不抛错中断 */
function render(){
  try {
    var all = getAllVariables();
    var d = _.get(all, 'stat_data', {});
    var era = _.get(d, '系统变量.时空切片', '古代');

    // 头部
    var titleMap = { '古代': '◆ 梅绛雪 · 古代 ◇', '现代': '◆ 梅绛雪 · 现代 ◇' };
    $('#gf-title').text(titleMap[era] || titleMap['古代']);
    $('#gf-era').text(era);
    $('#gf-date').text(
      _.get(d, '系统变量.日期', '') + '　' + _.get(d, '系统变量.时间段', '')
    );

    // 梅绛雪主体
    $('#gf-ym-loc').text('◆ ' + _.get(d, '梅绛雪.当前位置', ''));
    dots('gf-ym-dots', 'gf-ym-num', _.get(d, '梅绛雪.好感度', 0));
    $('#gf-ym-appear').text(_.get(d, '梅绛雪.外貌', ''));
    renderClothes(d, '梅绛雪', 'gf-ym-clothes');
    $('#gf-ym-pose').text(_.get(d, '梅绛雪.姿势', ''));
    $('#gf-ym-mind').text(_.get(d, '梅绛雪.心理', ''));
  } catch(e) {
    /* MVU 未就绪或变量缺失：保留 HTML 默认值（即 initvar 初始内容） */
  }
}

/* 初始化：先等 MVU 就绪，再渲染，再订阅变量更新事件 */
async function init(){
  await waitGlobalInitialized('Mvu');
  render();
  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, function(){
    render();
  });
}

$(errorCatched(init));
</script>
